conteudo.css:
:root {
    --cor-fundo: #ffffff;
    --cor-fonte: #000000;
    --cor-links: #0000ff;
    --cor-botao: #5b6af0;
    --cor-botao-hover: #4a59df;
}

body {
    background: linear-gradient(rgba(255, 255, 255, 1), rgba(232, 232, 255, 1));
    background-size: cover;
    color: var(--cor-fonte);
    font-family: Arial, sans-serif;
    font-size: 18px;
    font-weight: 400;
    line-height: 1.5;
    margin: 24px;
    padding: 24px;
}

header {
    border-radius: 8px;
    box-shadow: none;
    padding: 24px;

}

.grade-conteudo {
    align-items: flex-start;
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 24px;
    justify-content: flex-start;
}

.grade-conteudo > * {
    flex: 1 1 calc(100% - 24px);
    min-width: 0;
}

nav a {
    color: var(--cor-links);
    margin-right: 16px;
    text-decoration: underline;
}

img, .cartao-conteudo, table, .botao-cta {
    border-radius: 8px;
    box-shadow: none;
}

img { max-width: 100%; width: auto; }
.botao-cta { background: var(--cor-botao); color: #fff; display: inline-block; padding: 10px 16px; text-decoration: none; }
.botao-cta:hover { background: var(--cor-botao-hover); }
.formulario-contato { display: grid; gap: 12px; max-width: 520px; }
.formulario-contato input, .formulario-contato textarea { border: 1px solid var(--cor-links); border-radius: 8px; padding: 10px; }

@media (max-width: 700px) {
    .grade-conteudo { flex-direction: column; }
    .grade-conteudo > * { flex-basis: auto; width: 100%; }
}

